import{_ as n,o as a,c as o,a2 as t}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/BNF.md","filePath":"manual-en/BNF.md","lastUpdated":1785684581000}'),r={name:"manual-en/BNF.md"};function s(i,e,l,d,m,c){return a(),o("div",null,[...e[0]||(e[0]=[t('<h3 id="_6-10-backus-naur-form" tabindex="-1">6.10 Backus-Naur Form <a class="header-anchor" href="#_6-10-backus-naur-form" aria-label="Permalink to &quot;6.10 Backus-Naur Form&quot;">​</a></h3><p>The syntax of some parts of the PSPP language is presented in this manual using the formalism known as <em>Backus-Naur Form</em> , or BNF. The following table describes BNF:</p><ul><li>Words in all-uppercase are PSPP keyword tokens. In BNF, these are often called <em>terminals</em>. There are some special terminals, which are written in lowercase for clarity:</li></ul><p><code>number</code></p><p>A real number.</p><p><code>integer</code></p><p>An integer number.</p><p><code>string</code></p><p>A string.</p><p><code>var-name</code></p><p>A single variable name.</p><p><code>=</code>, <code>/</code>, <code>+</code>, <code>-</code>, etc.</p><p>Operators and punctuators.</p><p><code>.</code></p><p>The end of the command. This is not necessarily an actual dot in the syntax file (see <a href="./Commands">Commands</a>).</p><ul><li>Other words in all lowercase refer to BNF definitions, called <em>productions</em>. These productions are also known as <em>nonterminals</em>. Some nonterminals are very common, so they are defined here in English for clarity:</li></ul><p><code>var-list</code></p><p>A list of one or more variable names or the keyword <code>ALL</code>.</p><p><code>expression</code></p><p>An expression. See <a href="./Expressions">Expressions</a>, for details.</p><ul><li>‘::=’ means “is defined as”. The left side of ‘::=’ gives the name of the nonterminal being defined. The right side of ‘::=’ gives the definition of that nonterminal. If the right side is empty, then one possible expansion of that nonterminal is nothing. A BNF definition is called a <em>production</em>.</li><li>So, the key difference between a terminal and a nonterminal is that a terminal cannot be broken into smaller parts—in fact, every terminal is a single token (see <a href="./Tokens">Tokens</a>). On the other hand, nonterminals are composed of a (possibly empty) sequence of terminals and nonterminals. Thus, terminals indicate the deepest level of syntax description. (In parsing theory, terminals are the leaves of the parse tree; nonterminals form the branches.)</li><li>The first nonterminal defined in a set of productions is called the <em>start symbol</em>. The start symbol defines the entire syntax for that command.</li></ul>',21)])])}const f=n(r,[["render",s]]);export{h as __pageData,f as default};
